parameters.jsCode:
const errorRaw = $json.error ?? $json.errorMessage ?? '';
const errorText = typeof errorRaw === 'string'
  ? errorRaw.trim()
  : String(errorRaw?.description ?? errorRaw?.message ?? '').trim();

if (errorText) {
  if (/503|service unavailable|high demand|alta demanda|saturad/i.test(errorText)) {
    return [{ json: { message: 'El modelo está saturado en este momento. La acción puede haberse ejecutado antes del corte; revisá el resultado antes de repetirla para no duplicarla.' } }];
  }
  return [{ json: { message: 'No pude terminar el pedido por un error interno. No voy a asumir que la acción se completó; probá nuevamente en unos segundos.' } }];
}

const raw = $json.respuesta ?? $json.output ?? $json.text ?? $json.message ?? '';
const respuesta = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw);

if (!respuesta) {
  return [{ json: { message: 'No pude generar una respuesta esta vez. Probá de nuevo en unos segundos.' } }];
}

const esAudioYaEnviado = /audio mandado|nota de voz generada|audio generado/i.test(respuesta);
if (esAudioYaEnviado) return [];

// Gemini a veces termina mostrando una segunda llamada al buscador como texto,
// aun cuando Tavily ya devolvió resultados válidos. Rescatamos esos datos del
// nodo ejecutado para no perder precios ni enlaces por un fallo de formato.
const resultadosWeb = () => {
  try {
    const items = $('Buscar en Internet').all();
    const encontrados = [];
    for (const item of items) {
      const raiz = item?.json ?? item ?? {};
      const listas = [raiz.results, raiz.response?.results, raiz.data?.results];
      for (const lista of listas) {
        if (Array.isArray(lista)) encontrados.push(...lista);
      }
    }
    const vistos = new Set();
    return encontrados.filter(resultado => {
      const url = String(resultado?.url ?? '').trim();
      if (!/^https?:\/\//i.test(url) || vistos.has(url)) return false;
      vistos.add(url);
      return true;
    });
  } catch (_) {
    return [];
  }
};

const formatearResultadosWeb = (resultados, consulta = '') => {
  const opciones = resultados.slice(0, 5).map((resultado, indice) => {
    const titulo = String(resultado?.title ?? 'Resultado').replace(/\s+/g, ' ').trim();
    const contenido = String(resultado?.content ?? '').replace(/\s+/g, ' ').trim();
    const precio = `${titulo} ${contenido}`.match(/(?:\$|ARS\s*)\s*(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{2})?/i)?.[0]?.replace(/\s+/g, ' ');
    const url = String(resultado?.url ?? '').trim();
    return `${indice + 1}. ${titulo}${precio ? ` — ${precio}` : ''}\n${url}`;
  });
  const asunto = consulta ? ` para "${consulta}"` : '';
  return `Encontré estas opciones${asunto}:\n\n${opciones.join('\n\n')}\n\nLos precios, el stock y el costo de envío pueden cambiar; confirmalos en cada enlace antes de comprar.`;
};

// Si un proveedor devuelve como texto una invocación que no fue ejecutada, nunca
// mostramos el protocolo interno y distinguimos la operación que quedó pendiente.
if (/^calling\s+(?:default_api:)?(?:buscar[_ ]en[_ ]internet|search[_ ]in[_ ]tavily)\b/i.test(respuesta)) {
  const consulta = respuesta.match(/(?:query|consulta)\s*[:=]\s*[\"']?([^}\n\"']+)/i)?.[1]?.trim();
  const encontrados = resultadosWeb();
  if (encontrados.length) {
    return [{ json: { message: formatearResultadosWeb(encontrados, consulta) } }];
  }
  const detalle = consulta ? ` sobre "${consulta}"` : '';
  return [{ json: { message: `No pude completar la búsqueda web${detalle}. Reintentá en unos segundos; todavía no tengo un resultado verificado.` } }];
}
if (/^calling\s+(?:default_api:)?ejecutar_comando_pc\b/i.test(respuesta)) {
  return [{ json: { message: 'El comando de la PC quedó sin ejecutar. Repetilo una vez; no voy a afirmar que se hizo hasta recibir la confirmación del equipo.' } }];
}
if (/^calling\s+/i.test(respuesta)) {
  return [{ json: { message: 'La respuesta del modelo llegó en un formato interno inválido. Reintentá el pedido en unos segundos.' } }];
}

// Telegram admite 4096 caracteres. Dejamos margen y partimos por párrafos o líneas.
const limite = 3800;
const partes = [];
let restante = respuesta;
while (restante.length > limite) {
  let corte = restante.lastIndexOf('\n\n', limite);
  if (corte < limite * 0.55) corte = restante.lastIndexOf('\n', limite);
  if (corte < limite * 0.55) corte = restante.lastIndexOf(' ', limite);
  if (corte < 1) corte = limite;
  partes.push(restante.slice(0, corte).trim());
  restante = restante.slice(corte).trim();
}
if (restante) partes.push(restante);
return partes.map(message => ({ json: { message } }));

for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.fileExtension = 'ogg';
  }
}
return $input.all();

const raw = String($json.output ?? $json.text ?? $json.message ?? '').trim();
const error = $json.error ?? $json.errorMessage ?? '';
const esComando = /^Calling\s+(?:(?:default_api:)?ejecutar_comando_pc)\b/i.test(raw);
if (!esComando) return [{ json: { recuperar_herramienta: false, respuesta: raw, error } }];

let cuerpo = raw.replace(/^Calling\s+(?:(?:default_api:)?ejecutar_comando_pc)\s*/i, '');
cuerpo = cuerpo.replace(/^with\s+input\s*:\s*/i, '').trim();
let datos = {};
try {
  datos = JSON.parse(cuerpo);
} catch (_) {
  const valor = nombre => {
    const patron = new RegExp(`${nombre}\\s*:\\s*(?:["']([^"']*)["']|([^,}]*))`, 'i');
    const coincidencia = cuerpo.match(patron);
    return String(coincidencia?.[1] ?? coincidencia?.[2] ?? '').trim();
  };
  datos = {
    accion: valor('accion'), parametro: valor('parametro'), parametro2: valor('parametro2'),
    parametro3: valor('parametro3'), parametro4: valor('parametro4')
  };
}
if (!datos.accion) {
  return [{ json: { recuperar_herramienta: false, respuesta: 'No pude interpretar la acción. Repetí el pedido una vez.' } }];
}
return [{ json: {
  recuperar_herramienta: true,
  accion: String(datos.accion || ''), parametro: String(datos.parametro || ''),
  parametro2: String(datos.parametro2 || ''), parametro3: String(datos.parametro3 || ''),
  parametro4: String(datos.parametro4 || '')
} }];

const errorRaw = $json.error ?? $json.errorMessage ?? '';
const errorText = typeof errorRaw === 'string' ? errorRaw : String(errorRaw?.message ?? errorRaw?.description ?? '');
if (errorText) {
  return [{ json: { message: 'No pude comunicarme con Rebecca Core para recuperar el comando. La acción no quedó confirmada.' } }];
}
const estado = String($json.status || 'error');
const mensaje = String($json.message || $json.detail || 'La acción no devolvió una respuesta.');
return [{ json: { message: estado === 'success' ? mensaje : `No pude completar la acción: ${mensaje}` } }];

const item = $input.first().json;
const original = String(item.text ?? item.message?.text ?? '').trim();
const pedido = original.replace(/^\s*(?:rebecca|rebeca|becca)\s*[,;:!-]?\s*/i, '').trim();
const normal = pedido.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const variasAcciones = /\s+(?:y|ademas|tambien)\s+(?:me\s+)?(?:abr|pon|reproduc|paus|continu|siguient|anterior|mostr|consult|imprim)/i.test(normal);

let ruta = 'agente';
let accion = '';
let parametro = '';
let consultaWeb = '';

if (!item.message?.photo && !variasAcciones) {
  const ampliarNoticia = pedido.match(/^(?:quiero\s+(?:saber|conocer)\s+m[aá]s|contame\s+m[aá]s|ampl[ií](?:a|ame)|explicame\s+m[aá]s)\s+(?:(?:sobre|de)\s+)?(.+)$/i);
  let temaNoticia = ampliarNoticia?.[1]?.trim() || '';
  if (/\bnoticia\b/i.test(pedido) && temaNoticia) {
    temaNoticia = temaNoticia
      .replace(/^(?:la\s+)?(?:primera|segunda|tercera)\s+noticia\s*[,;:]?\s*(?:esa\s+de\s+)?/i, '')
      .replace(/^(?:esa\s+)?noticia\s+(?:de|sobre)\s+/i, '')
      .replace(/^de\s+/i, '')
      .trim();
  }
  const tituloExplicito = temaNoticia.split(/\s+/).filter(Boolean).length >= 4;
  const borrarPedidos = /^(?:(?:quiero|necesito)\s+que\s+|(?:podes|podrias)\s+)?(?:elimin\w*|borr\w*|quit\w*|sac\w*|vola\w*)\s+(?:(?:el|la|los|las|mi|mis)\s+)?(?:pedidos?|trabajos?)(?:\s+pendientes?)?\b/.test(normal);
  const idsPedidos = [...normal.matchAll(/#(\d+)/g)].map(coincidencia => coincidencia[1]);
  if (/\bnoticia\b/i.test(pedido) && tituloExplicito) {
    ruta = 'comando'; accion = 'explicar_noticia'; parametro = temaNoticia;
  } else if (borrarPedidos && idsPedidos.length) {
    ruta = 'comando'; accion = 'gestion_lote_pedidos';
    parametro = [...new Set(idsPedidos)].map(id => `eliminar:#${id}`).join('|');
  } else if (/\b(?:captura|pantallazo|screenshot)\b/.test(normal)) {
    ruta = 'captura';
  } else if (/\bimprim(?:i|e|ir|ime)?\b.*\bmesa(?:\s+de\s+trabajo)?\b|\bmesa(?:\s+de\s+trabajo)?\b.*\bimprim/.test(normal)) {
    ruta = 'imprimir_mesa';
  } else if (/\b(?:clima|temperatura|pronostico)\b/.test(normal) || /^(?:que\s+tiempo\s+hace|como\s+esta\s+el\s+tiempo)\b/.test(normal)) {
    ruta = 'clima';
  } else if (/^(?:cual\s+es\s+el\s+)?estado(?:\s+(?:de\s+)?(?:la\s+)?(?:pc|computadora|equipo))?[?!.]*$/.test(normal)) {
    ruta = 'estado_pc';
  } else if (/^(?:(?:minimiza|minimizar|mostra|mostrar)\s+(?:todo|el escritorio|(?:todas\s+)?las ventanas)|(?:(?:subi|subir|aumenta|aumentar|baja|bajar|disminui|disminuir)\s+(?:el\s+)?(?:volumen|audio|sonido))|(?:mutea|mutear|silencia|silenciar)(?:\s+(?:el\s+)?(?:volumen|audio|sonido))?)$/.test(normal)) {
    ruta = 'comando'; accion = 'sistema'; parametro = pedido;
  } else if (/\b(?:pausa|pausar|pausa|para|deten)\w*\b.*\b(?:musica|cancion|tema|reproduccion)\b/.test(normal)) {
    ruta = 'comando'; accion = 'pausar_musica';
  } else if (/\b(?:continua|continuar|reanuda|reanudar|segui|seguir)\w*\b.*\b(?:musica|cancion|tema|reproduccion)\b/.test(normal)) {
    ruta = 'comando'; accion = 'continuar_musica';
  } else if (/^(?:(?:pasa|salta|cambia)\w*\s+(?:a\s+)?(?:la\s+)?)?(?:siguiente|proxima)(?:\s+(?:cancion|tema|musica|reproduccion))?[?!.]*$/.test(normal)) {
    ruta = 'comando'; accion = 'siguiente_cancion';
  } else if (/^(?:(?:pasa|salta|cambia|volve)\w*\s+(?:a\s+)?(?:la\s+)?)?(?:anterior|previa)(?:\s+(?:cancion|tema|musica|reproduccion))?[?!.]*$/.test(normal)) {
    ruta = 'comando'; accion = 'anterior_cancion';
  } else if (/\bestado\b.*\b(?:musica|reproduccion|cancion)\b/.test(normal)) {
    ruta = 'comando'; accion = 'estado_musica';
  } else if (/\b(?:gustos?|perfil|aprendiste|conoces)\b.*\b(?:musica|musical(?:es)?|canciones?|artistas?)\b/.test(normal)) {
    ruta = 'comando'; accion = 'perfil_musical';
  } else {
    const abrir = pedido.match(/^(?:me\s+)?(?:abri|abrí|abre|abres|abrime|ábreme|abrir|inicia|iniciá|iniciar|ejecuta|ejecutá|ejecutar|lanza|lanzá|lanzar)\s+(?:(?:el|la)\s+)?(.+?)(?:\s+(?:por\s+favor|porfa|please))?[?!.]*$/i);
    if (abrir?.[1]) {
      ruta = 'comando'; accion = 'abrir_programa'; parametro = abrir[1].trim();
    } else if (/^(?:poneme|ponéme|ponme|pone|poné|pon|reproduc\w*|busca\w*|dame|quiero\s+escuchar)\b.*\b(?:musica|cancion|tema|metal|rock|playlist)\b/.test(normal)) {
      ruta = 'comando'; accion = 'buscar_musica';
      parametro = pedido.replace(/^(?:poneme|ponéme|ponme|pone|poné|pon|reproduc\w*|busca\w*|dame|quiero\s+escuchar)\s*/i, '').trim() || 'música para escuchar';
    } else if (/^(?:mostra\w*|lista\w*|consulta\w*|cuales\s+son)\b.*\b(?:pedidos|trabajos)\s+pendientes\b/.test(normal)) {
      ruta = 'comando'; accion = 'reporte_pedidos';
    } else if (/^(?:mostra\w*|lista\w*|consulta\w*|cuales\s+son)\b.*\brecordatorios\b/.test(normal)) {
      ruta = 'comando'; accion = 'consultar_recordatorios';
    } else if (/^(?:mostra\w*|lista\w*|consulta\w*|cuales\s+son)\b.*\bdeudas\b/.test(normal)) {
      ruta = 'comando'; accion = 'consultar_deudas';
    } else if (/^(?:mostra\w*|lista\w*|consulta\w*)\b.*\bstock\b/.test(normal)) {
      ruta = 'comando'; accion = 'consultar_stock';
    } else if (/^(?:mostra\w*|lista\w*|consulta\w*)\b.*\blista\s+de\s+precios\b/.test(normal)) {
      ruta = 'comando'; accion = 'listar_precios';
    } else {
      const ordenBusqueda = /^(?:(?:necesito|quiero|podes|podrias|puedes|me ayudas a)\s+(?:que\s+)?)?(?:busca|buscar|buscame|busque|busques|averigua|averiguar|investiga|investigar|compara|comparar|googlea|googlear|encontra|encontrar)\b/.test(normal);
      const pedidoLocal = /\b(?:pedido|trabajo|recordatorio|deuda|turno|archivo|carpeta)\b/.test(normal);
      const datoComercial = /\b(?:precio|precios|comprar|mayorista|proveedor|comercio|stock)\b/.test(normal);
      const fuenteExterna = /\b(?:internet|web|online|google|fuente|fuentes|link|links|enlace|enlaces|noticia|noticias|actual)\b/.test(normal);
      const ubicacionCompra = /\b(?:cerca|TU_CIUDAD|zona oeste|amba|mercadolibre|argentina)\b/.test(normal);
      const buscoInformacionExterna = /\bbusco\b/.test(normal) && (datoComercial || fuenteExterna);
      if ((ordenBusqueda && !pedidoLocal) || buscoInformacionExterna || (datoComercial && ubicacionCompra)) {
        ruta = 'web';
      }
    }
  }
}

// Operaciones explícitas del dueño: una sola transacción, sin depender del modelo.
const comercio = /^(?:vendi\b|(?:registra\w*|anota\w*|modifica\w*|corrige|corregi|anula\w*|cancela\w*)\s+(?:(?:una|la)\s+)?venta\b|(?:cambia|actualiza|fija)(?: el)? precio\b|(?:las?|los?)\s+.+?\s+(?:(?:tienen? un nuevo precio[,;]?\s*)?(?:ahora\s+)?(?:salen?|cuestan?|vale[n]?)\s+\$?\d)|(?:marca\w*|pone|pon)\s+(?:(?:el|los)\s+)?pedidos?\s+#?\d|(?:mostrame|mostrar|lista|listar|ver|consulta|consultar)(?: las)? ventas\b)/.test(normal);
if (comercio && !item.message?.photo) {
  ruta = 'comando'; accion = 'gestionar_comercio'; parametro = pedido;
}
let claveComercio = '';
if (comercio) {
  let origen = item;
  try { origen = $('Telegram Trigger').all()[0]?.json || item; } catch (_) {}
  const chat = origen.message?.chat?.id;
  const id = origen.message?.message_id;
  if (chat !== undefined && id !== undefined) claveComercio = `telegram:${chat}:${id}`;
}

if (ruta === 'web') {
  consultaWeb = pedido
    .replace(/^(?:(?:necesito|quiero|podes|podrias|puedes|me ayudas a)\s+(?:que\s+)?)?(?:busca\w*|averigua\w*|investiga\w*|compara\w*|googlea\w*|encontra\w*)\s+(?:en\s+internet\s+)?/i, '')
    .trim() || pedido;
  const normalConsulta = consultaWeb.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const pareceCompra = /\b(?:taza|remera|buzo|gorra|insumo|sublim|producto|maquina|impresora|tinta|papel|vinilo|precio|comprar|mayorista|proveedor|stock)\w*\b/.test(normalConsulta);
  if (pareceCompra && !/\b(?:precio|comprar|mayorista|proveedor|venta)\b/.test(normalConsulta)) {
    consultaWeb += ' precio mayorista proveedor venta';
  }
  if (pareceCompra && !/\b(?:argentina|buenos aires|TU_CIUDAD|zona oeste|amba)\b/.test(normalConsulta)) {
    consultaWeb += ' Argentina';
  }
  consultaWeb = consultaWeb.slice(0, 280);
}

return [{ json: {
  ...item,
  ruta_rapida: ruta,
  accion_rapida: accion,
  parametro_rapido: parametro,
  consulta_web: consultaWeb,
  parametro2_rapido: '', parametro3_rapido: '', parametro4_rapido: claveComercio
} }];

const errorRaw = $json.error ?? $json.errorMessage ?? '';
const errorText = typeof errorRaw === 'string' ? errorRaw : String(errorRaw?.message ?? errorRaw?.description ?? '');
if (errorText) {
  return [{ json: { message: 'No pude comunicarme con Rebecca Core. El comando no se confirmó y no voy a fingir que se ejecutó.' } }];
}
const estado = String($json.status || 'error');
const mensaje = String($json.message || $json.detail || 'El equipo no devolvió una confirmación.');
return [{ json: { message: estado === 'success' ? mensaje : `No pude completar el comando: ${mensaje}` } }];

const errorRaw = $json.error ?? $json.errorMessage ?? '';
const error = typeof errorRaw === 'string'
  ? errorRaw.trim()
  : String(errorRaw?.message ?? errorRaw?.description ?? '').trim();
const consulta = String($json.query ?? '').trim();
const resultadosCrudos = Array.isArray($json.results) ? $json.results : [];
const limpiar = valor => String(valor ?? '').replace(/\s+/g, ' ').trim();
const consultaNormal = consulta.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const esCompra = /\b(?:taza|remera|buzo|gorra|insumo|sublim|producto|maquina|impresora|tinta|papel|vinilo|precio|comprar|mayorista|proveedor|stock)\w*\b/.test(consultaNormal);
const normalizarPalabras = valor => limpiar(valor)
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/https?:\/\//g, ' ').replace(/[^a-z0-9]+/g, ' ').trim()
  .split(/\s+/).filter(Boolean)
  .map(palabra => palabra.length > 4 && palabra.endsWith('s') ? palabra.slice(0, -1) : palabra);
const palabrasVacias = new Set([
  'argentina','aires','amba','buenos','buscar','busca','comprar','compra','cerca','TU_CIUDAD',
  'internet','mayorista','online','para','precio','proveedor','stock','venta','web','zona','oeste',
  'necesito','quiero','podes','podrias','averigua','investiga','compara','encontra'
]);
const tokensConsulta = [...new Set(normalizarPalabras(consulta).filter(token => token.length >= 3 && !/^\d+$/.test(token) && !palabrasVacias.has(token)))];
const ancla = tokensConsulta[0] || '';
const vistos = new Set();
const resultados = resultadosCrudos.map(resultado => {
  const url = String(resultado?.url ?? '').trim();
  if (!/^https?:\/\//i.test(url) || vistos.has(url)) return null;
  vistos.add(url);
  const tituloUrl = new Set(normalizarPalabras(`${resultado?.title ?? ''} ${url}`));
  const contenido = new Set(normalizarPalabras(resultado?.content ?? ''));
  const fuertes = tokensConsulta.filter(token => tituloUrl.has(token));
  const debiles = tokensConsulta.filter(token => !tituloUrl.has(token) && contenido.has(token));
  const coincidencias = fuertes.length + debiles.length;
  const minimo = tokensConsulta.length <= 1 ? tokensConsulta.length : Math.min(2, Math.ceil(tokensConsulta.length * 0.5));
  const anclaFuerte = !ancla || tituloUrl.has(ancla);
  if (tokensConsulta.length && (coincidencias < minimo || !anclaFuerte)) return null;
  const scoreTavily = Number(resultado?.score ?? 0);
  return {...resultado, _relevancia: fuertes.length * 4 + debiles.length + (Number.isFinite(scoreTavily) ? scoreTavily : 0)};
}).filter(Boolean).sort((a, b) => b._relevancia - a._relevancia).slice(0, 5);

if (error) {
  return [{json:{message:'Tavily no pudo completar la búsqueda esta vez. La cancelé rápido para no dejarte esperando; probá nuevamente en unos segundos.'}}];
}
if (!resultados.length) {
  const detalle = consulta ? ` para "${consulta}"` : '';
  const motivo = resultadosCrudos.length
    ? `Encontré páginas, pero las descarté porque no coincidían suficientemente con ${esCompra ? 'el producto pedido' : 'el tema pedido'}.`
    : 'No encontré resultados verificables.';
  const sugerencia = esCompra
    ? 'Probá agregando marca, medida, material o modelo exacto.'
    : 'Probá formulando una consulta más concreta o indicando qué tipo de fuente necesitás.';
  return [{json:{message:`${motivo}${detalle} ${sugerencia}`}}];
}

const opciones = resultados.map((resultado, indice) => {
  const titulo = limpiar(resultado.title) || 'Resultado';
  const contenido = limpiar(resultado.content);
  const precio = `${titulo} ${contenido}`.match(/(?:\$|ARS\s*)\s*(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{2})?/i)?.[0]?.replace(/\s+/g, ' ');
  const resumen = contenido.length > 180 ? `${contenido.slice(0, 177).trim()}...` : contenido;
  const url = limpiar(resultado.url);
  return `${indice + 1}. ${titulo}${precio ? ` — ${precio}` : ''}${resumen ? `\n${resumen}` : ''}\n${url}`;
});
const asunto = consulta ? ` para "${consulta}"` : '';
const descartados = Math.max(0, resultadosCrudos.length - resultados.length);
const notaFiltro = descartados ? ` Descarté ${descartados} resultado${descartados === 1 ? '' : 's'} que no coincidían bien.` : '';
let mensaje = `Encontré ${resultados.length} opción${resultados.length === 1 ? '' : 'es'} relevante${resultados.length === 1 ? '' : 's'}${asunto}.${notaFiltro}\n\n${opciones.join('\n\n')}\n\nPrecio, stock y envío pueden cambiar; confirmalos en el enlace antes de comprar.`;
if (mensaje.length > 3800) mensaje = `${mensaje.slice(0, 3760).trim()}\n\nResultados recortados para Telegram.`;
return [{json:{message:mensaje}}];
